#version 300 es
precision highp float;

// VisualSynth uniforms
uniform float uTime;
uniform float uFrame;
uniform float uFps;
uniform float uRms;

// Audio uniforms
uniform float audioLow;      // bass
uniform float audioLowSmooth; // bass_att
uniform float audioMid;      // mid
uniform float audioMidSmooth; // mid_att
uniform float audioHigh;     // treb
uniform float audioHighSmooth; // treb_att

// Screen uniforms
uniform float uAspectX;
uniform float uAspectY;
uniform vec2 uAspect;
uniform vec2 uTexSize;

// Random values
uniform vec2 uRandomPreset;
uniform vec2 uRandomFrame;

// Input from vertex shader
in vec2 vUv;
in float vRadius;
in float vAngle;

// Output
out vec4 fragColor;

// Textures
uniform sampler2D sampler_main;
uniform sampler2D sampler_noise_lq;
uniform sampler2D sampler_noise_mq;
uniform sampler2D sampler_noise_hq;
uniform sampler2D sampler_blur1;
uniform sampler2D sampler_blur2;
uniform sampler2D sampler_blur3;

// Helper functions
float clamp01(float x) { return clamp(x, 0.0, 1.0); }
vec2 clamp01(vec2 x) { return clamp(x, vec2(0.0), vec2(1.0)); }
vec3 clamp01(vec3 x) { return clamp(x, vec3(0.0), vec3(1.0)); }
vec4 clamp01(vec4 x) { return clamp(x, vec4(0.0), vec4(1.0)); }

// Texture helper functions
vec4 GetPixel(vec2 uv) { return texture(sampler_main, uv); }
vec4 GetBlur1(vec2 uv) { return texture(sampler_blur1, uv); }
vec4 GetBlur2(vec2 uv) { return texture(sampler_blur2, uv); }
vec4 GetBlur3(vec2 uv) { return texture(sampler_blur3, uv); }


void main() {
  vec4 ret = vec4(0.0);
  vec2 uv = vUv;
  float rad = vRadius;

uvc = (vUv-0.5) * uAspect.xy + 0.5 -centre;
omask = clamp01(15*(0.55-uvc.y));
uv2 = project (uvc) * vec2(1,1.5);
vec2 ring = (texture(sampler_noise_mq,-uTime/16+length(uv2)/2)-0.5).xy*sat(1-length(uv2));
vUv += ring.xy *(1-omask)*.02;

vec3 retl = max(GetPixel(vUv-hor),GetPixel(vUv-hor.yx));
vec3 retr = GetPixel(vUv+hor);
vec3 rets = max(retl,retr)*min(0.3+vRadius*2,1);
struc = max(max(GetPixel(vUv),rets)*vec3(2,2,.7+1-2*blue)*1.3,GetBlur2(vUv)*q1*3);
ret = struc;

uv3 = (ring.x*0.2+ (uv2-0)*.25 +0.5+centre/uAspect.xy);
uv3 = fract(uv3);
ret += GetBlur1(uv3)*sat(2-length(uv2));

//Planet
ir0 = 24*(.15/(pos.y-0.1))/uAspect.y;
uv1 = (uvc-pos);
k1 = sqrt(abs(1-ir0*ir0*uv1.y*uv1.y)+0.0); //sollte sqrt sein, 0.01 = test
rs = vec2 (acos(uv1.x*ir0/k1), uv1.y*ir0/k1);
mask = ir0*length(uv1)<1;
rs = rs/14+vec2(uTime*-0.007,0);
prof  = noise3(rs);
prof2 = noise3(rs+uTexSize.zw);
float hmask = sat(4-8*pos.y);

ret *= !mask;
ret += struc*mask*hmask; //struc vor dem Planeten zeigen

uv4 = ((uvc-0.5)*.1 +0.5+centre/uAspect.xy);
ret += sat (-dot(uv1,uvc-0.5))*mask*hmask*140*GetBlur1(uv4);

ret += ((-uv1.y/ir0*20)*vec3(0,0.4,0.9)+lavcol(sat(prof)*pow(k1,4)))*mask;
ret += -mask * sat (dot(-prof+prof2,uv1))*50;

ret += texture(sampler_noise_hq,uv2/4+ring.x*0.1).r*blue* !mask*sat(1.3-length(uv2)) * vec3(0.2,0,1);


z = 1/(2-vUv.y) ;
uv3 = vec2(uvc.x-.5,1)*z*vec2(q8,q9)+vec2(0,uTime*0.005);
uv3.y -= noise3(uv3).r*-0.008;
uv4 = ((uvc-vec2 (q12,0.3))*.4 +0.5+centre/uAspect.xy);
ret += !mask*clamp01(1-2*uvc.y)*2*clamp01(noise3(uv3).r*GetBlur2(uv4)+vec3(0,0.1,0.25));

  fragColor = ret;
}

