vec4 GetBlur1(vec2 uv) { return texture(sampler_blur1, uv); }
vec4 GetBlur2(vec2 uv) { return texture(sampler_blur2, uv); }
vec4 GetBlur3(vec2 uv) { return texture(sampler_blur3, uv); }


void main() {
  vec4 ret = vec4(0.0);
  vec2 uv = vUv;
  float rad = vRadius;

    //Horizontally centered and scaled coordinates
    //vec2 p = (vUv * uTexSize.xy * 2.0 - vec2(uTexSize.x, 0.0)) / uTexSize.y;
    //Centered version:
    vec2 p = (vUv * uTexSize.xy * 2.0 - uTexSize.xy) / uTexSize.y;

    //Quick noise pattern
    float n = mod(dot(p, sin(p.yx)),.00001);
    // RGBA wave frequencies
    vec4 f = vec4(.7, 1, 1.3 ,0);
    // RGBA wave offsets
    vec4 o = vec4(0, 1, 2, 0);

    // Calculate wave pattern for each color channel
    vec4 waves = p.y + .3 * cos(uTime + n + p.x * f + o);

    //XorDev - told me to replace tanh(x) with 1-exp(-x), which it works.
    vec3 result = .2 / abs(waves); //Make this as a separate result.
    ret = 1-exp(-result); //Then output tonemapping without thresholding.

  fragColor = ret;
}

